  it.todo("Blinker oscillates from vertical to horizontal — [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");
  it.todo("Blinker oscillates back to vertical after two generations — [(-1,1),(0,1),(1,1)] -> [(0,0),(0,1),(0,2)]");
  it.todo("handles negative coordinates — blinker at [(-5,-5),(-5,-4),(-5,-3)] -> [(-6,-4),(-5,-4),(-4,-4)]");
});

